action.command:
set -e
cd /tmp/pbin
cat > Program.cs <<'EOF'
using System;
using System.Reflection;
using Bovis.Web;
using Microsoft.AspNetCore.Builder;

class Probe {
  static void Main(string[] args) {
    // Force-load Bovis.Web (and its dependency closure) exactly as the app does.
    var asm = Assembly.LoadFrom(AppContext.BaseDirectory + "Bovis.Web.dll");
    // The REAL builder path the server uses: WebApplication.CreateBuilder + AddEnvVars + LoadJsonFromDir + ConfigurableBinder + configStore.
    var builder = Program.CreateAndSetupBuilder(Array.Empty<string>(), setupDatabase: true);
    var globals = asm.GetType("Bovis.Web.Globals", true);
    string boundCookie = (string)globals.GetField("AuthCookie", BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);
    string boundPub = (string)globals.GetField("PublicBaseUrl", BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);
    string boundUsers = null;
    // Also read the config the app holds for the admin user section
    var usersCfg = builder.Configuration.GetSection("Bovis.Web:Users");
    Console.WriteLine("REAL-PATH Globals.AuthCookie    = " + boundCookie);
    Console.WriteLine("REAL-PATH Globals.PublicBaseUrl = " + boundPub);
    Console.WriteLine("CONFIG Bovis.Web:AuthCookie     = " + builder.Configuration["Bovis.Web:AuthCookie"]);
    Console.WriteLine("CONFIG Users[0].Name            = " + usersCfg[0]["Name"]);
    Console.WriteLine("CONFIG Users[0].HashedPassword  = " + usersCfg[0]["HashedPassword"]);
    Console.WriteLine("COOKIE == appsettings(appsettings.json UIH234...) ? " + (boundCookie == "UIH234dcbjn0934723dwmZSIZL2342423KUOWidsqw6123e"));
    Console.WriteLine("COOKIE length = " + (boundCookie==null?"null":boundCookie.Length));
  }
}
EOF
cat > probe.csproj <<'EOF'
<Project Sdk="Microsoft.NET.Sdk.Web">
  <PropertyGroup>
    <OutputType>Exe</OutputType>
    <TargetFramework>net8.0</TargetFramework>
    <Nullable>disable</Nullable>
    <ImplicitUsings>disable</ImplicitUsings>
    <EnableDefaultCompileItems>false</EnableDefaultCompileItems>
    <AssemblyName>probe</AssemblyName>
  </PropertyGroup>
  <ItemGroup>
    <Compile Include="Program.cs" />
    <Reference Include="Bovis.Web"><HintPath>Bovis.Web.dll</HintPath></Reference>
  </ItemGroup>
</Project>
EOF
rm -rf bin obj
echo "=== build ==="
dotnet build -v q -nologo 2>&1 | tail -4
echo "=== run real-path probe (env matches server) ==="
cd /workspace/src/Bovis.Web && ASPNETCORE_ENVIRONMENT=Development ASPNETCORE_URLS=http://localhost:5195 timeout 120 dotnet /tmp/pbin/bin/Debug/net8.0/probe.dll 2>&1 | grep -E "REAL-PATH|CONFIG|COOKIE|Exception|error" | head -20

